<?php if(!empty($wishlist_enabled)): ?>
<style>
.mp-wishlist-link{display:inline-flex!important;align-items:center;gap:6px;padding:8px 12px;border:1px solid currentColor;border-radius:999px;color:inherit;text-decoration:none;font:inherit;font-size:13px;line-height:1.2;white-space:nowrap}
.mp-wishlist-link-count{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;border-radius:99px;background:var(--mp-primary,#111);color:#fff;font-size:10px;font-weight:700}
.mp-wishlist-heart{position:absolute;z-index:8;top:10px;right:10px;width:38px;height:38px;display:inline-flex;align-items:center;justify-content:center;border:1px solid rgba(20,20,20,.12);border-radius:50%;background:rgba(255,255,255,.94);color:#292524;font-size:21px;line-height:1;cursor:pointer;box-shadow:0 2px 10px rgba(0,0,0,.10)}
.mp-wishlist-heart[aria-pressed="true"]{color:#bd2e4b}.mp-wishlist-heart:disabled{opacity:.55;cursor:wait}
.mp-wishlist-heart.fx-card-wishlist{opacity:1;color:#292524}.mp-wishlist-heart.fx-card-wishlist[aria-pressed="true"]{color:#bd2e4b}
.mp-wishlist-notice{position:fixed;z-index:100200;left:50%;bottom:22px;transform:translateX(-50%);max-width:calc(100vw - 28px);padding:12px 18px;border-radius:999px;background:#171717;color:#fff;font:600 13px/1.4 system-ui,sans-serif;box-shadow:0 8px 24px rgba(0,0,0,.22)}
@media(max-width:600px){.mp-wishlist-heart{top:7px;right:7px;width:36px;height:36px}.mp-wishlist-link{padding:7px 10px}}
</style>
<script>
(function(){
  var cfg={enabled:true,signedIn:<?= !empty($wishlist_signed_in) ? 'true' : 'false'; ?>,ids:<?= json_encode(array_values(array_map('intval', $wishlist_item_ids ?? []))); ?>,url:<?= json_encode($wishlist_url ?? ''); ?>,toggle:<?= json_encode($wishlist_toggle_url ?? ''); ?>,verify:<?= json_encode($wishlist_verify_url ?? ''); ?>,csrfName:<?= json_encode($this->security->get_csrf_token_name()); ?>,csrfHash:<?= json_encode($this->security->get_csrf_hash()); ?>};
  if(!cfg.enabled)return;
  var saved={};(cfg.ids||[]).forEach(function(id){saved[Number(id)]=true;});
  function announce(message){var n=document.querySelector('.mp-wishlist-notice');if(!n){n=document.createElement('div');n.className='mp-wishlist-notice';n.setAttribute('role','status');document.body.appendChild(n)}n.textContent=message;n.hidden=false;clearTimeout(n._timer);n._timer=setTimeout(function(){n.remove()},2600)}
  function heart(id){var b=document.createElement('button');b.type='button';b.className='mp-wishlist-heart';b.dataset.mpWishlist=String(id);b.setAttribute('aria-label',saved[id]?'Remove from wishlist':'Save to wishlist');b.setAttribute('aria-pressed',saved[id]?'true':'false');b.textContent=saved[id]?'♥':'♡';return b}
  function decorate(){
    document.querySelectorAll('button[class*="wishlist"]:not([data-mp-wishlist])').forEach(function(button){var link=button.closest('a[href*="/product/"]')||button.parentElement&&button.parentElement.closest('a[href*="/product/"]');if(!link)return;var match=link.href.match(/\/product\/(\d+)(?:[/?#]|$)/);if(!match)return;button.dataset.mpWishlist=match[1];button.classList.add('mp-wishlist-heart');button.setAttribute('type','button')});
    document.querySelectorAll('button[data-mp-wishlist]').forEach(function(button){var id=Number(button.dataset.mpWishlist);if(!id)return;button.classList.add('mp-wishlist-heart');button.setAttribute('aria-pressed',saved[id]?'true':'false');button.setAttribute('aria-label',saved[id]?'Remove from wishlist':'Save to wishlist')});
    document.querySelectorAll('a[href*="/product/"]').forEach(function(link){var match=link.href.match(/\/product\/(\d+)(?:[/?#]|$)/);if(!match)return;var id=Number(match[1]);if(!id||document.querySelector('.mp-wishlist-heart[data-mp-wishlist="'+id+'"]'))return;var card=link.closest('article,li,[class*="product-card"],[class*="product_card"],[class*="-card"],[class*="_card"],[class*="product-tile"]');if(!card)card=link.parentElement&&link.parentElement.parentElement;if(!card)return;if(getComputedStyle(card).position==='static')card.style.position='relative';card.appendChild(heart(id));});
    var detail=location.pathname.match(/\/product\/(\d+)\/?$/);if(detail&&!document.querySelector('.mp-wishlist-detail')){var add=document.querySelector('button[onclick*="addToCart"],button[onclick*="addDetailToCart"],button[id*="detail-add"],button[id*="product-add"]');if(add){var b=heart(Number(detail[1]));b.classList.add('mp-wishlist-detail');b.style.position='static';b.style.width='auto';b.style.height='auto';b.style.padding='10px 15px';b.style.borderRadius='999px';b.style.gap='7px';b.textContent=(saved[Number(detail[1])]?'♥ Saved':'♡ Save to wishlist');add.parentNode.insertBefore(b,add);}}
    var navs=Array.prototype.slice.call(document.querySelectorAll('header nav, nav'));var nav=navs.find(function(n){return /cart|account|menu/i.test(n.textContent||'')})||navs[0];if(nav&&!nav.querySelector('.mp-wishlist-link')){var a=document.createElement('a');a.className='mp-wishlist-link';a.href=cfg.url;a.innerHTML='Wishlist <span class="mp-wishlist-link-count">'+Object.keys(saved).length+'</span>';nav.appendChild(a)}
  }
  function update(){document.querySelectorAll('.mp-wishlist-heart').forEach(function(b){var id=Number(b.dataset.mpWishlist),on=!!saved[id];b.setAttribute('aria-pressed',on?'true':'false');b.setAttribute('aria-label',on?'Remove from wishlist':'Save to wishlist');b.textContent=b.classList.contains('mp-wishlist-detail')?(on?'♥ Saved':'♡ Save to wishlist'):(on?'♥':'♡')});document.querySelectorAll('.mp-wishlist-link-count').forEach(function(n){n.textContent=Object.keys(saved).length})}
  document.addEventListener('click',function(e){var b=e.target.closest('[data-mp-wishlist]');if(!b)return;e.preventDefault();e.stopPropagation();if(!cfg.signedIn){location.href=cfg.verify+'&item='+encodeURIComponent(b.dataset.mpWishlist);return}var id=Number(b.dataset.mpWishlist),body=new URLSearchParams({item_id:String(id)});if(cfg.csrfName)body.set(cfg.csrfName,cfg.csrfHash);b.disabled=true;fetch(cfg.toggle,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body.toString()}).then(function(r){return r.json()}).then(function(res){if(res.csrf_hash)cfg.csrfHash=res.csrf_hash;if(res.login_required){location.href=res.redirect;return}if(!res.status)throw new Error(res.message||'Could not update wishlist');if(res.saved)saved[id]=true;else delete saved[id];update();if(!res.saved&&/\/wishlist\/?$/.test(location.pathname)){location.reload();return}announce(res.saved?'Added to your wishlist':'Removed from your wishlist')}).catch(function(err){announce(err.message||'Could not update wishlist')}).finally(function(){b.disabled=false})},true);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',decorate);else decorate();
  new MutationObserver(function(){decorate()}).observe(document.documentElement,{childList:true,subtree:true});
})();
</script>
<?php endif; ?>
